class GraphAlgebraCompatibilityTest {

	@Test
	void unknownSailReceivesLegacyAlgebraByDefault() {
		SailConnection unknown = mock(SailConnection.class, CALLS_REAL_METHODS);
		SailRepositoryConnection connection = new SailRepositoryConnection(mock(SailRepository.class), unknown);

		SailTupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);

		assertEquals(0, graphNodes(query.getParsedQuery().getTupleExpr()));
	}

	@Test
	void wrappingUnknownSailDoesNotImplyGraphSupport() {
		SailConnection unknown = mock(SailConnection.class, CALLS_REAL_METHODS);
		SailConnection wrapper = new SailConnectionWrapper(unknown);
		SailRepositoryConnection connection = new SailRepositoryConnection(mock(SailRepository.class), wrapper);

		SailTupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);

		assertEquals(0, graphNodes(query.getParsedQuery().getTupleExpr()));
	}

	@Test
	void unknownSailUpdateWhereReceivesLegacyAlgebra() {
		SailConnection unknown = mock(SailConnection.class, CALLS_REAL_METHODS);
		SailRepositoryConnection connection = new SailRepositoryConnection(mock(SailRepository.class), unknown);
		SailUpdate update = (SailUpdate) connection.prepareUpdate(
				"INSERT { ?s <urn:copy> ?o } WHERE { GRAPH ?g { ?s <urn:p> ?o } }");

		Modify modify = (Modify) update.getParsedUpdate().getUpdateExprs().get(0);
		assertEquals(0, graphNodes(modify.getWhereExpr()));
	}

	@Test
	void transparentWrapperPreservesCapabilityButUnknownSubclassDoesNot() {
		SailConnection supported = mock(SailConnection.class, CALLS_REAL_METHODS);
		when(supported.supportsGraphAlgebra()).thenReturn(true);
		SailConnection transparent = new SailConnectionWrapper(supported);
		SailConnection unknown = new SailConnectionWrapper(supported) {
		};
		SailRepository repository = mock(SailRepository.class);

		var graph = new SailRepositoryConnection(repository, transparent)
				.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);
		var legacy = new SailRepositoryConnection(repository, unknown)
				.prepareTupleQuery(QueryLanguage.SPARQL, "SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);
		assertEquals(1, graphNodes(graph.getParsedQuery().getTupleExpr()));
		assertEquals(0, graphNodes(legacy.getParsedQuery().getTupleExpr()));
	}

	@Test
	void repositoryWrapperForwardsExplicitModeAndAllPreparationKinds() {
		SailConnection unknown = mock(SailConnection.class, CALLS_REAL_METHODS);
		SailRepository repository = mock(SailRepository.class);
		SailRepositoryConnection connection = new SailRepositoryConnection(repository, unknown);
		RepositoryConnectionWrapper wrapper = new RepositoryConnectionWrapper(repository, connection);
		wrapper.setQueryParseOptions(QueryParseOptions.STRICT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));

		SailTupleQuery tuple = (SailTupleQuery) wrapper.prepareTupleQuery("SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }");
		SailGraphQuery construct = (SailGraphQuery) wrapper.prepareGraphQuery(
				"CONSTRUCT { ?s ?p ?o } WHERE { GRAPH ?g { ?s ?p ?o } }");
		SailBooleanQuery ask = (SailBooleanQuery) wrapper.prepareBooleanQuery("ASK { GRAPH ?g { ?s ?p ?o } }");
		SailQuery generic = (SailQuery) wrapper.prepareQuery("SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }");
		assertEquals(1, graphNodes(tuple.getParsedQuery().getTupleExpr()));
		assertEquals(1, graphNodes(construct.getParsedQuery().getTupleExpr()));
		assertEquals(1, graphNodes(ask.getParsedQuery().getTupleExpr()));
		assertEquals(1, graphNodes(generic.getParsedQuery().getTupleExpr()));
		assertEquals(QueryParseOptions.STRICT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH),
				connection.getQueryParseOptions());
	}

	@Test
	void explicitModeDoesNotQueryEvaluatorCapability() {
		SailConnection unknown = mock(SailConnection.class, CALLS_REAL_METHODS);
		when(unknown.supportsGraphAlgebra()).thenThrow(new AssertionError("Explicit mode must skip capability lookup"));
		SailRepositoryConnection connection = new SailRepositoryConnection(mock(SailRepository.class), unknown);
		for (GraphAlgebraMode mode : new GraphAlgebraMode[] { GraphAlgebraMode.LEGACY, GraphAlgebraMode.GRAPH }) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode));
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL,
					"SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }", null);
			assertEquals(mode, query.getParsedQuery().getParseOptions().graphAlgebraMode());
		}
	}

	@Test
	void repositoryWrapperAlgebraConsumersMustSelectLegacyExplicitly() {
		SailConnection supported = mock(SailConnection.class, CALLS_REAL_METHODS);
		when(supported.supportsGraphAlgebra()).thenReturn(true);
		SailRepository repository = mock(SailRepository.class);
		SailRepositoryConnection connection = new SailRepositoryConnection(repository, supported) {
		};
		RepositoryConnectionWrapper extension = new RepositoryConnectionWrapper(repository, connection) {
		};

		// Repository wrappers delegate preparation; their presence is invisible to the evaluator capability lookup.
		SailTupleQuery graph = (SailTupleQuery) extension.prepareTupleQuery("SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }");
		assertEquals(1, graphNodes(graph.getParsedQuery().getTupleExpr()));

		extension.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
		SailTupleQuery legacy = (SailTupleQuery) extension
				.prepareTupleQuery("SELECT * WHERE { GRAPH ?g { ?s ?p ?o } }");
		assertEquals(0, graphNodes(legacy.getParsedQuery().getTupleExpr()));
	}

	private static int graphNodes(TupleExpr expression) {
		int[] count = { 0 };
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph graph) {
				count[0]++;
				super.meet(graph);
			}
		});
		return count[0];
	}
}
